// Small shims so the same web code runs in Electron (EXE/DMG), Capacitor (APK) and a browser.

export const isElectron = !!window.bfdiDesktop;
export const isCapacitor = !!window.Capacitor?.isNativePlatform?.();

export async function openExternal(url) {
  if (isElectron) return window.bfdiDesktop.openExternal(url);
  const Browser = window.Capacitor?.Plugins?.Browser;
  if (isCapacitor && Browser) return Browser.open({ url });
  window.open(url, '_blank', 'noopener');
}

/** Build-time config (www/js/config.js is generated by scripts/write-config.mjs and never committed). */
export async function loadBuildConfig() {
  if (globalThis.BFDI_CONFIG) return globalThis.BFDI_CONFIG; // single-file builds (tools/make_site.mjs)
  try {
    const mod = await import('./config.js');
    return mod.default || {};
  } catch {
    return {};
  }
}

export async function copyText(text) {
  if (isElectron) return window.bfdiDesktop.copy(text);
  return navigator.clipboard.writeText(text);
}

/** System notification (desktop) or a browser notification when allowed. */
export function notify(title, body) {
  if (isElectron) { window.bfdiDesktop.notify(title, body); return; }
  try {
    if ('Notification' in window && Notification.permission === 'granted') new Notification(title, { body });
  } catch { /* not available (Android web view) */ }
}
